    const panels = kinds.map((kind, i) => ({ ...newPanel(kind, i === 0 ? '/' : home), x: columns === 2 ? 0 : i * 2, y: columns === 2 ? i * 2 : 0, w: 2, h: 2 }));
    if (columns === 4 && width >= 760 && height >= 480) {
