    const largest = [...ws.panels].filter(p => p.w > 1 || p.h > 1).sort((a, b) => b.w * b.h - a.w * a.h)[0];
    if (!largest)
        return false;
    return split(ws, largest.id, panel, largest.w >= largest.h && largest.w > 1 ? 'right' : 'bottom');
