export type Rect = Pick<Panel, 'x' | 'y' | 'w' | 'h'>;
export function gridDrop(ws: Workspace, x: number, y: number, width: number, height: number): Rect | undefined {
    if (width <= 0 || height <= 0 || x < 0 || y < 0 || x >= width || y >= height) return;
